const SITE={name:'AnswerCalcs',url:'https://answercalcs.com',email:'hello@answercalcs.com'};
const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
const weekdays=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const fmt=n=>new Intl.NumberFormat('en-US').format(n);
const todayUTC=(d=new Date())=>new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()));
const addDays=(d,n)=>{const x=new Date(d);x.setUTCDate(x.getUTCDate()+n);return x};
const ymd=d=>`${months[d.getUTCMonth()]} ${d.getUTCDate()}, ${d.getUTCFullYear()}`;
const dayOfYear=d=>Math.floor((d-new Date(Date.UTC(d.getUTCFullYear(),0,0)))/86400000);
const workdays=(a,b)=>{let n=0,d=new Date(a);while(d<b){d=addDays(d,1);const w=d.getUTCDay();if(w!==0&&w!==6)n++}return n};
const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));

const CSS=`:root{--bg:#f7faff;--ink:#071b45;--muted:#66758d;--line:#dde7f4;--blue:#1769ff;--soft:#eef5ff}*{box-sizing:border-box}body{margin:0;background:linear-gradient(#fbfdff,#f6f9ff);color:var(--ink);font:15px/1.55 Inter,system-ui,-apple-system,Segoe UI,sans-serif}a{color:inherit;text-decoration:none}.top,main,footer{max-width:1240px;margin:auto}.top{height:72px;display:flex;align-items:center;gap:30px;padding:0 24px;border-bottom:1px solid var(--line)}.brand{font-weight:900;font-size:20px;display:flex;gap:10px;align-items:center}.logo{width:32px;height:32px;border-radius:11px;display:grid;place-items:center;background:#fff;border:1px solid #cfe0fa;color:var(--blue);box-shadow:0 8px 25px #1769ff1a}.top nav{margin-left:auto;display:flex;gap:24px}.top nav a{font-weight:650;font-size:14px;color:#294567}.cta{padding:10px 16px;border-radius:999px;background:var(--blue);color:#fff;font-weight:800}.hero{padding:70px 20px 38px;display:grid;grid-template-columns:1.05fr .95fr;gap:44px;align-items:center}.eyebrow{font-size:12px;letter-spacing:.18em;color:var(--blue);font-weight:900}.hero h1,.tool h1,.legal h1{font-family:Georgia,serif;font-size:clamp(42px,5vw,70px);line-height:1;letter-spacing:-.045em;margin:16px 0}.hero h1 span{color:var(--blue)}.lede{font-size:18px;color:var(--muted);max-width:680px}.search{margin-top:26px;display:flex;background:#fff;border:1px solid #cfe0f2;border-radius:18px;padding:7px;box-shadow:0 18px 50px #2d68ad16}.search input{border:0;outline:0;flex:1;padding:0 14px;font:inherit;background:transparent}.search button,.calc button{border:0;border-radius:13px;background:var(--blue);color:#fff;padding:14px 18px;font-weight:850}.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}.chips a{border:1px solid var(--line);background:#fff;padding:7px 11px;border-radius:999px;font-size:12px;color:#3b5675}.hero-card,.answer,.cat,.toolcard,.calc,.prose,.side{background:#fff;border:1px solid var(--line);border-radius:24px;box-shadow:0 20px 55px #214d8912}.hero-card{padding:28px}.live{display:inline-block;background:#e5fbef;color:#0a8455;padding:6px 9px;border-radius:999px;font-size:11px;font-weight:800;float:right}.big{font-size:clamp(40px,5vw,62px);font-weight:950;color:var(--blue);letter-spacing:-.05em;margin:24px 0}.metrics{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);margin-top:20px}.metrics div{padding:16px 8px}.metrics small{display:block;color:#8090a4}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding:0 20px 20px}.cat,.toolcard{padding:20px;transition:.2s}.cat:hover,.toolcard:hover{transform:translateY(-2px);border-color:#aac9ff}.cat h2,.toolcard b{font-size:17px}.cat p,.toolcard p{color:var(--muted);margin-bottom:0}.section{padding:44px 20px}.section h2{font-size:28px;margin:0 0 6px}.tools{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}.trust{margin:14px 20px 52px;padding:20px;border:1px solid var(--line);border-radius:20px;display:grid;grid-template-columns:repeat(4,1fr);text-align:center;background:linear-gradient(90deg,#f2f7ff,#fbfdff)}.trust b{display:block;font-size:22px;color:var(--blue)}.tool{padding:34px 20px 20px}.crumbs{font-size:12px;color:#7c8da3;margin-bottom:24px}.toolgrid{display:grid;grid-template-columns:1fr .9fr;gap:34px;align-items:start}.tool h1{font-size:clamp(38px,4.3vw,60px)}.answer{padding:28px;min-height:240px}.answer .big{margin:16px 0}.statgrid{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--line)}.statgrid div{padding:14px}.statgrid small{display:block;color:#8191a6}.content{display:grid;grid-template-columns:1fr 320px;gap:34px;padding:24px 20px 70px}.prose,.side{padding:24px}.prose h2{margin-top:30px}.direct{background:var(--soft);border:1px solid #cfe0fa;border-radius:16px;padding:18px}.facts{list-style:none;padding:0}.facts li,.side a{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid var(--line)}.calc{margin-top:20px;padding:18px;display:grid;gap:12px}.calc label{display:flex;justify-content:space-between;gap:10px;align-items:center}.calc input,.calc select{padding:10px;border:1px solid #cfdbeb;border-radius:10px;min-width:140px}.calc output{padding:13px;text-align:center;border-radius:11px;background:var(--soft);font-weight:900;color:var(--blue)}.legal{padding:70px 20px 90px;max-width:900px!important}.legal h1{font-size:52px}.directory{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:30px}.directory a{padding:18px;border:1px solid var(--line);border-radius:16px;background:#fff}footer{border-top:1px solid var(--line);padding:30px 24px 42px;display:flex;justify-content:space-between;color:#708198}.dark{filter:invert(.92) hue-rotate(180deg)}@media(max-width:900px){.top nav{display:none}.hero,.toolgrid,.content{grid-template-columns:1fr}.grid,.tools{grid-template-columns:1fr 1fr}.trust{grid-template-columns:1fr 1fr}.content{gap:14px}footer{flex-direction:column;align-items:center;text-align:center;gap:10px}.footlinks{justify-content:center}}@media(max-width:560px){body{font-size:14px}.top{height:64px;padding:0 16px}.brand{font-size:18px}.logo{width:30px;height:30px}.cta{display:none}main{padding:0 16px}.hero{padding:34px 0 26px;gap:24px;min-height:0}.hero h1{font-size:37px;line-height:1.02;margin:13px 0 16px}.lede{font-size:16px;line-height:1.55;margin-bottom:20px}.search{margin-top:20px;border-radius:16px;padding:6px;display:grid;grid-template-columns:1fr}.search input{min-height:42px;padding:0 12px}.search button{width:100%;height:46px}.chips{gap:7px}.chips a{padding:7px 10px}.hero-card{padding:22px;border-radius:22px}.card-head{gap:8px}.big,.answer-main{font-size:38px;line-height:1.03;margin:18px 0}.metrics,.answer-stats{grid-template-columns:1fr 1fr}.metrics div,.answer-stats div{padding:13px 8px}.grid{grid-template-columns:1fr;padding:0;gap:10px}.cat{min-height:0;padding:18px 20px;border-radius:18px}.cat h2{margin:0 0 6px;font-size:16px}.cat p{margin:0;min-height:0;font-size:13px}.section{padding:32px 0 8px}.section-head{align-items:flex-start}.section h2{font-size:25px}.tools,.directory{grid-template-columns:1fr;gap:10px}.tool-card,.toolcard{padding:16px;border-radius:17px;min-height:118px}.tool-card b,.toolcard b{font-size:14px}.tool-card p,.toolcard p{margin:6px 0 0;font-size:12px;line-height:1.4}.trend{margin-left:0;margin-right:0}.trust{margin:28px 0 34px;padding:10px;gap:0;border-radius:18px}.trust>div{padding:14px 8px}.trust b{font-size:18px}.trust span{display:block;font-size:12px;color:#6f849d}.tool-hero{padding:28px 0 16px}.tool h1,.tool-hero h1{font-size:38px}.answer{padding:22px;min-height:0}.content{padding:18px 0 44px}.prose,.side{padding:20px}.legal,.listing{padding:48px 0 60px}.legal h1,.listing h1{font-size:40px}footer{padding:24px 18px 32px;flex-direction:column;align-items:center;text-align:center;gap:8px}.footlinks{justify-content:center;flex-wrap:wrap}.mini-note{text-align:center}}`;

function page({title,desc,path='/',body,robots='index,follow'}){const full=title.includes(SITE.name)?title:`${title} | ${SITE.name}`;const url=`${SITE.url}${path}`;const ld={"@context":"https://schema.org","@type":path==='/'?'WebSite':'WebPage',name:full,description:desc,url,isPartOf:path==='/'?undefined:{"@type":"WebSite",name:SITE.name,url:SITE.url}};const json=JSON.stringify(ld).replace(/</g,'\\u003c');return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(full)}</title><meta name="description" content="${esc(desc)}"><meta name="robots" content="${robots}"><link rel="canonical" href="${url}"><meta property="og:type" content="website"><meta property="og:title" content="${esc(full)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${url}"><meta name="theme-color" content="#f7faff"><link rel="manifest" href="/manifest.webmanifest"><script type="application/ld+json">${json}</script><style>${CSS}</style></head><body>${nav()}<main>${body}</main>${footer()}<script>${JS}</script></body></html>`}
function nav(){return `<header class="top"><a class="brand" href="/"><span class="logo">✦</span>AnswerCalcs</a><nav><a href="/time-date/">Time & Date</a><a href="/calculators/">Calculators</a><a href="/converters/">Converters</a><a href="/tools/">All tools</a></nav><a class="cta" href="/tools/">Explore tools →</a></header>`}
function footer(){return `<footer><strong>AnswerCalcs</strong><span>Everyday calculators and date tools.</span><span><a href="/about/">About</a> · <a href="/privacy/">Privacy</a> · <a href="/terms/">Terms</a> · <a href="/contact/">Contact</a></span></footer>`}
function home(){const popular=[['Days Until Christmas','/days-until/christmas/'],['30 Days From Today','/days-from-today/30/'],['Percentage Calculator','/percentage-calculator/'],['Loan Payment Calculator','/loan-calculator/'],['Compound Interest Calculator','/compound-interest-calculator/'],['Salary to Hourly','/salary-calculator/'],['GPA Calculator','/gpa-calculator/'],['Length Converter','/length-converter/'],['Running Pace Calculator','/pace-calculator/']];return page({title:'Free everyday calculators, date tools & countdowns',desc:'Instant calculators and countdowns for dates, time, percentages and everyday questions.',body:`<section class="hero"><div><div class="eyebrow">TIME · DATE · MATH · CONVERSIONS</div><h1>Instant answers for <span>time, dates, numbers</span> and daily life.</h1><p class="lede">Quick calculators and countdowns for everyday questions. Type what you need or choose a tool below.</p><form class="search" id="search"><input id="q" placeholder="Try: 30 days from today, how long until 5 PM…"><button>Find answer →</button></form><div class="chips"><a href="/days-until/christmas/">Christmas countdown</a><a href="/weeks-from-today/6/">6 weeks from today</a><a href="/age-calculator/">Age calculator</a></div></div><div class="hero-card"><span class="live">● Live result</span><b>How long until 5:00 PM?</b><div class="big" id="hero">Calculating…</div><div class="metrics"><div><small>Minutes</small><b id="mins">—</b></div><div><small>Seconds</small><b id="secs">—</b></div><div><small>Target</small><b>5 PM</b></div><div><small>Mode</small><b>Local</b></div></div></div></section><section class="grid"><a class="cat" href="/time-date/"><h2>Countdown Tools</h2><p>Live time-left and date-offset answers.</p></a><a class="cat" href="/time-date/"><h2>Date Calculators</h2><p>Add, subtract and compare dates.</p></a><a class="cat" href="/age-calculator/"><h2>Age & Birthday</h2><p>Exact age from a birth date.</p></a><a class="cat" href="/calculators/"><h2>Percent & Money</h2><p>Percentages and tip math.</p></a><a class="cat" href="/converters/"><h2>Converters</h2><p>Everyday unit and time conversions.</p></a><a class="cat" href="/tools/"><h2>All Tools</h2><p>Browse the complete utility directory.</p></a></section><section class="section"><div class="section-head"><div><div class="eyebrow">QUICK ANSWERS</div><h2>Popular tools</h2><p>Start with the questions people use most often.</p></div></div><div class="tools">${popular.map(([t,u])=>`<a class="toolcard" href="${u}"><b>${t}</b><p>Open instant calculator →</p></a>`).join('')}</div></section><section class="trust"><div><b>Time & Date</b><span>countdowns and offsets</span></div><div><b>Everyday Math</b><span>percentages and tips</span></div><div><b>Date Tools</b><span>days, weeks and workdays</span></div><div><b>Converters</b><span>quick everyday conversions</span></div></section>`})}
function toolShell(title,desc,path,answer,stats,extra='',related=null){
 const links=related||[['30 days from today','/days-from-today/30/'],['90 days from today','/days-from-today/90/'],['6 weeks from today','/weeks-from-today/6/'],['Until 5 PM','/how-long-until/5-pm/']];
 return page({title,desc,path,body:`<section class="tool"><div class="crumbs"><a href="/">Home</a> › <a href="/tools/">Tools</a> › ${esc(title)}</div><div class="toolgrid"><div><div class="eyebrow">DIRECT ANSWER</div><h1>${esc(title)}</h1><p class="lede">${esc(desc)}</p>${extra}</div><div class="answer"><span class="live">● Live result</span><div class="big">${answer}</div><div class="statgrid">${stats.map(([a,b])=>`<div><small>${a}</small><b>${b}</b></div>`).join('')}</div></div></div></section><section class="content"><article class="prose"><div class="direct"><b>Direct answer</b><p>${desc}</p></div><h2>How it is calculated</h2><p>This page uses a direct formula or calendar rule and shows the result from the values above. Change the inputs when a calculator is available to get a new result instantly.</p><h2>Accuracy note</h2><p>Check your inputs, units and date or time assumptions. For important financial, legal, medical or tax decisions, verify the result independently.</p></article><aside class="side"><h3>Related answers</h3>${links.map(([t,u])=>`<a href="${u}">${t} <span>→</span></a>`).join('')}</aside></section>`})
}
function daysFromToday(n,now=new Date()){n=Math.max(1,Math.min(3650,+n||1));const a=todayUTC(now),d=addDays(a,n);return toolShell(`${n} Days From Today`,`The exact date ${n} calendar days from today is ${ymd(d)}.`,`/days-from-today/${n}/`,ymd(d),[['Weekday',weekdays[d.getUTCDay()]],['Business days',fmt(workdays(a,d))],['Day of year',dayOfYear(d)],['Calendar days',fmt(n)]])}
function weeksFromToday(n,now=new Date()){n=Math.max(1,Math.min(520,+n||1));const d=addDays(todayUTC(now),n*7);return toolShell(`${n} Week${n===1?'':'s'} From Today`,`${n} week${n===1?'':'s'} from today is ${ymd(d)}.`,`/weeks-from-today/${n}/`,ymd(d),[['Days',fmt(n*7)],['Weekday',weekdays[d.getUTCDay()]],['Hours',fmt(n*168)],['Day of year',dayOfYear(d)]])}
function hoursFromNow(n){n=Math.max(1,Math.min(240,+n||1));return toolShell(`${n} Hour${n===1?'':'s'} From Now`,`Adds ${n} hours to your device's current time.`,`/hours-from-now/${n}/`,`<span data-hours="${n}">Calculating…</span>`,[['Hours',n],['Minutes',fmt(n*60)],['Seconds',fmt(n*3600)],['Mode','Local']])}
function parseTime(slug){const m=slug.match(/^(\d{1,2})(?:-(\d{1,2}))?-(am|pm)$/);if(!m)return null;const h=+m[1],min=+(m[2]||0),ap=m[3];if(h<1||h>12||min>59)return null;return{h,min,ap,label:`${h}:${String(min).padStart(2,'0')} ${ap.toUpperCase()}`}}
function howLongUntil(slug){const p=parseTime(slug);if(!p)return null;return toolShell(`How Long Until ${p.label}?`,`Live countdown to ${p.label} in your device's local time.`,`/how-long-until/${slug}/`,`<span class="countdown" data-h="${p.h}" data-m="${p.min}" data-ap="${p.ap}">Calculating…</span>`,[['Target',p.label],['Time zone','Your device'],['Updates','Every second'],['Cost','Free']])}
const events={christmas:[11,25,'Christmas Day'],halloween:[9,31,'Halloween'],'new-years-day':[0,1,"New Year's Day"]};
function daysUntilEvent(slug,now=new Date()){const e=events[slug];if(!e)return null;const a=todayUTC(now);let d=new Date(Date.UTC(a.getUTCFullYear(),e[0],e[1]));if(d<a)d=new Date(Date.UTC(a.getUTCFullYear()+1,e[0],e[1]));const n=Math.round((d-a)/86400000);return toolShell(`How Many Days Until ${e[2]}?`,`${fmt(n)} days remain until ${e[2]} on ${ymd(d)}.`,`/days-until/${slug}/`,`${fmt(n)} days`,[['Date',ymd(d)],['Weeks',(n/7).toFixed(1)],['Hours',fmt(n*24)],['Weekday',weekdays[d.getUTCDay()]]])}
