'discount-calculator':['Discount Calculator','Calculate sale price and amount saved after a percentage discount.','<div class="calc"><label>Original price <input id="price" inputmode="decimal" value="100"></label><label>Discount % <input id="discount" inputmode="decimal" value="20"></label><button onclick="discountCalc()">Calculate</button><output id="o">$80.00 · save $20.00</output></div>'],
